<template><ion-page><ion-header><ion-toolbar><ion-buttons slot="start"><ion-back-button default-href="/professor/home"/></ion-buttons><ion-title><span class="toolbar-page-title">Nova atividade</span><span class="toolbar-brand-right">Task<span>Edu</span></span></ion-title></ion-toolbar></ion-header><ion-content><main class="form-page wide-form"><header class="form-hero"><span>NOVA PUBLICAÇÃO</span><h1>Crie um novo compromisso</h1><p>Preencha as informações que serão exibidas para a turma.</p></header><section class="form-card"><AtividadeForm :salvando="salvando" :erro="erro" @salvar="salvar"/></section></main></ion-content></ion-page></template>
<script setup lang="ts">import { ref } from 'vue';import { useRouter } from 'vue-router';import { IonBackButton,IonButtons,IonContent,IonHeader,IonPage,IonTitle,IonToolbar,toastController } from '@ionic/vue';import AtividadeForm,{type FormAtividade} from '../components/AtividadeForm.vue';import { criarAtividade } from '../services/atividades.service';import { getUsuarioAtual } from '../services/auth.service';const router=useRouter(),usuario=getUsuarioAtual(),salvando=ref(false),erro=ref('');async function salvar(dados:FormAtividade){if(!usuario.value)return;salvando.value=true;erro.value='';try{await criarAtividade({...dados,dataEntrega:new Date(`${dados.data}T${dados.horario||'23:59'}:00`),professorId:usuario.value.uid,professorNome:usuario.value.nome});const toast=await toastController.create({message:'Atividade publicada com sucesso!',duration:1800,color:'success',position:'top'});await toast.present();await router.replace('/professor/home')}catch(e){erro.value=e instanceof Error?e.message:'Não foi possível publicar.'}finally{salvando.value=false}}</script>
